//! Copying ioctl arguments and the buffers they point to.
//!
//! `ddi::IoctlArg` copies a `zerocopy` type at the argument address. The
//! DRM argument structures are generated by bindgen and contain raw
//! pointers and padding, so they are not `zerocopy` types, and several
//! ioctls copy strings to and from user buffers that the argument points
//! to. This module does both with `ddi_copyin(9F)` and `ddi_copyout(9F)`
//! from `ddi-sys`, always with the `mode` of the ioctl so that kernel
//! callers through LDI (`FKIOCTL`) work. It is local to the DRM core until
//! the `ddi` crate grows an equivalent.
//!
//! Padding bytes are never invented by the kernel: an argument is either
//! copied in completely or starts zeroed, handlers change it only through
//! field assignments (the contract of the `unsafe` [`UserArg::get_mut`]),
//! and it is copied out byte for byte. No uninitialised kernel memory can
//! therefore reach the caller.

use core::ffi::c_void;
use core::mem::{MaybeUninit, size_of};

use ddi::{Errno, IoctlArg, sys};
use drm_uapi as uapi;

/// A `#[repr(C)]` uAPI structure for which every bit pattern is a valid
/// value: integers and raw pointers only.
///
/// # Safety
/// The implementing type must consist of integer and raw pointer fields
/// (possibly with padding) and have no invariants of its own.
pub unsafe trait Plain: Copy {}

// SAFETY: plain integers.
unsafe impl Plain for u16 {}
// SAFETY: plain integers.
unsafe impl Plain for u32 {}
// SAFETY: plain integers.
unsafe impl Plain for u64 {}

// SAFETY: integer and pointer fields only; see the bindings in drm-uapi.
unsafe impl Plain for uapi::drm_version {}
// SAFETY: as above.
unsafe impl Plain for uapi::drm_unique {}
// SAFETY: as above.
unsafe impl Plain for uapi::drm_auth {}
// SAFETY: as above.
unsafe impl Plain for uapi::drm_client {}
// SAFETY: as above.
unsafe impl Plain for uapi::drm_set_version {}
// SAFETY: as above.
unsafe impl Plain for uapi::drm_get_cap {}
// SAFETY: as above.
unsafe impl Plain for uapi::drm_set_client_cap {}
// SAFETY: as above.
unsafe impl Plain for uapi::drm_gem_close {}
// SAFETY: as above.
unsafe impl Plain for uapi::drm_gem_flink {}
// SAFETY: as above.
unsafe impl Plain for uapi::drm_gem_open {}
// SAFETY: as above.
unsafe impl Plain for uapi::drm_mode_create_dumb {}
// SAFETY: as above.
unsafe impl Plain for uapi::drm_mode_map_dumb {}
// SAFETY: as above.
unsafe impl Plain for uapi::drm_mode_destroy_dumb {}

/// An ioctl argument structure held in the kernel.
pub struct UserArg<T: Plain> {
    buf: MaybeUninit<T>,
}

impl<T: Plain> UserArg<T> {
    /// Copies the argument in from the caller. Fails with `EFAULT` if the
    /// address is not readable.
    pub fn read(arg: &IoctlArg<'_>) -> Result<UserArg<T>, Errno> {
        let mut buf = MaybeUninit::<T>::uninit();
        // SAFETY: the destination is size_of::<T>() bytes of our own stack;
        // ddi_copyin checks the source against the caller's address space.
        let r = unsafe {
            sys::ddi_copyin(arg.raw() as *const c_void, buf.as_mut_ptr() as *mut c_void, size_of::<T>(), arg.mode())
        };
        if r != 0 {
            return Err(Errno::EFAULT);
        }
        Ok(UserArg { buf })
    }

    /// Creates an all-zero argument, for commands that only copy out.
    pub fn zeroed() -> UserArg<T> {
        UserArg { buf: MaybeUninit::zeroed() }
    }

    /// Returns the argument.
    pub fn get(&self) -> &T {
        // SAFETY: every byte was written by ddi_copyin or zeroed, and every
        // bit pattern is a valid T (Plain).
        unsafe { self.buf.assume_init_ref() }
    }

    /// Returns the argument for modification.
    ///
    /// # Safety
    /// The caller may change the argument through assignments to its
    /// fields only, never by assigning or copying a whole `T` into it. A
    /// whole-value assignment may leave the padding bytes uninitialised, and
    /// [`UserArg::write`] would then copy kernel stack contents out to the
    /// caller.
    pub unsafe fn get_mut(&mut self) -> &mut T {
        // SAFETY: every byte is initialised and every bit pattern is a valid
        // T, as in get; the caller keeps the padding initialised.
        unsafe { self.buf.assume_init_mut() }
    }

    /// Copies the argument out to the caller. Fails with `EFAULT` if the
    /// address is not writable.
    pub fn write(&self, arg: &IoctlArg<'_>) -> Result<(), Errno> {
        // SAFETY: the source is the fully initialised buffer; ddi_copyout
        // checks the destination.
        let r = unsafe {
            sys::ddi_copyout(self.buf.as_ptr() as *const c_void, arg.raw() as *mut c_void, size_of::<T>(), arg.mode())
        };
        if r != 0 { Err(Errno::EFAULT) } else { Ok(()) }
    }
}

/// Copies `src` to the caller's buffer at `addr`, with the data model and
/// `FKIOCTL` handling of `arg`. Fails with `EFAULT`.
pub fn copy_out_bytes(arg: &IoctlArg<'_>, addr: usize, src: &[u8]) -> Result<(), Errno> {
    if src.is_empty() {
        return Ok(());
    }
    // SAFETY: src is a valid slice; ddi_copyout checks the destination.
    let r = unsafe { sys::ddi_copyout(src.as_ptr() as *const c_void, addr as *mut c_void, src.len(), arg.mode()) };
    if r != 0 { Err(Errno::EFAULT) } else { Ok(()) }
}

/// Fills `dst` from the caller's buffer at `addr`. Fails with `EFAULT`.
pub fn copy_in_bytes(arg: &IoctlArg<'_>, addr: usize, dst: &mut [u8]) -> Result<(), Errno> {
    if dst.is_empty() {
        return Ok(());
    }
    // SAFETY: dst is a valid mutable slice; ddi_copyin checks the source.
    let r = unsafe { sys::ddi_copyin(addr as *const c_void, dst.as_mut_ptr() as *mut c_void, dst.len(), arg.mode()) };
    if r != 0 { Err(Errno::EFAULT) } else { Ok(()) }
}
